export const palettes={aurora:[170,195,235,275,315],ember:[12,24,40,340,355],ocean:[175,190,205,220,250]};
// A fixed step renderer: no wall clock, Math.random, or live analyser state.
export class Renderer {
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.settings={theme:'aurora',strength:1,trail:'accumulate'};this.reset(1);}
 reset(seed){this.seed=seed>>>0;this.frame=0;this.last=[];this.ctx.globalCompositeOperation='source-over';const g=this.ctx.createLinearGradient(0,0,this.canvas.width,this.canvas.height);g.addColorStop(0,'#070e18');g.addColorStop(1,'#120e20');this.ctx.fillStyle=g;this.ctx.fillRect(0,0,this.canvas.width,this.canvas.height);}
 step(a){const c=this.ctx,w=this.canvas.width,h=this.canvas.height,t=this.frame/30,phase=(this.seed%10000)/1000,s=this.settings.strength,v=a.volume*s,b=a.bass*s,m=a.mid*s; if(this.settings.trail==='fade'){c.globalCompositeOperation='source-over';c.fillStyle='rgba(7,10,18,.018)';c.fillRect(0,0,w,h);}c.globalCompositeOperation='lighter';const colors=palettes[this.settings.theme];for(let j=0;j<7;j++){const q=t*.23+j*.9+phase;const x=w*(.5+.29*Math.sin(q*.83+.6*Math.sin(t*.11+phase))+.085*Math.cos(q*2.1+j));const y=h*(.5+.29*Math.cos(q*.61+j*.24)+.09*Math.sin(q*1.7));const p=this.last[j]||[x,y];if(v>.005){const hue=colors[j%colors.length];c.strokeStyle=`hsla(${hue},85%,68%,${Math.min(.5,.035+v*.16)})`;c.lineWidth=.6+v*2.8;c.shadowColor=`hsl(${hue},90%,60%)`;c.shadowBlur=5+b*15;c.beginPath();c.moveTo(...p);c.quadraticCurveTo((p[0]+x)/2+Math.sin(q*3)*m*8,(p[1]+y)/2,x,y);c.stroke();if(a.beat&&this.frame%7===0){c.shadowBlur=15;c.fillStyle=`hsla(${hue},90%,80%,.35)`;c.beginPath();c.arc(x,y,1+b*2,0,Math.PI*2);c.fill();}}this.last[j]=[x,y];}c.shadowBlur=0;c.globalCompositeOperation='source-over';this.frame++;}
}
